        while n > 1:
            # Find the index of the maximum element in arr
            max_index = find_max_position(arr, n)
            if max_index != n - 1:
                # Flip the array up to the maximum element
                arr = flip(arr, max_index + 1)
                # Flip the entire array to move the maximum element to the end
                arr = flip(arr, n)
            n -= 1
        return arr

    return sort(arr)

