    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def newman_prime(n):
    def nsw_number(n):
        if n == 0:
            return 1
        elif n == 1:
            return 1
        else:
            return 2 * nsw_number(n - 1) + nsw_number(n - 2)

    def find_nth_prime(n):
        count = 0
        i = 0
        while count < n:
            num = nsw_number(i)
            if is_prime(num):
                count += 1
                if count == n:
                    return num
            i += 1

    return find_nth_prime(n)
