def max_sub_array_sum_repeated(arr, n, k):
    def max_sub_array_sum(a, size):
        max_so_far = a[0]
        max_ending_here = a[0]
        for i in range(1, size):
            max_ending_here = max(a[i], max_ending_here + a[i])
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    def max_sub_array_wrap(a, n, k):
        max_kadane = max_sub_array_sum(a, n)
        max_prefix_sum = 0
        max_suffix_sum = 0
        pre_sum = 0
        suf_sum = 0
        for i in range(n):
