            max_prefix_sum = max(max_prefix_sum, pre_sum)
            suf_sum = pre_sum - a[i]
            max_suffix_sum = max(max_suffix_sum, suf_sum)
        return max(max_kadane, max_prefix_sum + max_suffix_sum * (k - 1))

    if k == 1:
        return max_sub_array_sum(arr, n)
    else:
        return max_sub_array_wrap(arr * k, n * k, k)

